// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        address owner = c.Owner();
        uint256 ownerBefore = owner.balance;
        uint256 zeroBefore = address(0).balance;
        bool ok = false;
        vm.prank(owner);
        try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok ? (address(0).balance == zeroBefore && owner.balance == ownerBefore + amount) : true);
    }
}
